DROP TABLE IF EXISTS `current`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `current` (
  `district` varchar(32) NOT NULL,
  `dt` datetime NOT NULL,
  `sunrise` datetime DEFAULT NULL,
  `sunset` datetime DEFAULT NULL,
  `temp` float DEFAULT NULL,
  `feels_like` float DEFAULT NULL,
  `pressure` int DEFAULT NULL,
  `humidity` int DEFAULT NULL,
  `dew_point` float DEFAULT NULL,
  `clouds` int DEFAULT NULL,
  `uvi` float DEFAULT NULL,
  `visibility` int DEFAULT NULL,
  `wind_speed` float DEFAULT NULL,
  `wind_gust` float DEFAULT NULL,
  `wind_deg` int DEFAULT NULL,
  `rain_1h` float DEFAULT NULL,
  `snow_1h` float DEFAULT NULL,
  `weather_id` int DEFAULT NULL,
  `weather_main` varchar(128) DEFAULT NULL,
  `weather_description` varchar(128) DEFAULT NULL,
  `weather_icon` varchar(32) DEFAULT NULL,
  PRIMARY KEY (`district`,`dt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
