--
-- Table structure for table `daily`
--

DROP TABLE IF EXISTS `daily`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `daily` (
  `district` varchar(32) NOT NULL,
  `dt` datetime NOT NULL,
  `future_dt` datetime NOT NULL,
  `sunrise` datetime DEFAULT NULL,
  `sunset` datetime DEFAULT NULL,
  `moonrise` datetime DEFAULT NULL,
  `moonset` datetime DEFAULT NULL,
  `moon_phase` float DEFAULT NULL,
  `summary` varchar(256) DEFAULT NULL,
  `temp_morn` float DEFAULT NULL,
  `temp_day` float DEFAULT NULL,
  `temp_eve` float DEFAULT NULL,
  `temp_night` float DEFAULT NULL,
  `temp_min` float DEFAULT NULL,
  `temp_max` float DEFAULT NULL,
  `feels_like_morn` float DEFAULT NULL,
  `feels_like_day` float DEFAULT NULL,
  `feels_like_eve` float DEFAULT NULL,
  `feels_like_night` float DEFAULT NULL,
  `pressure` int DEFAULT NULL,
  `humidity` int DEFAULT NULL,
  `dew_point` float DEFAULT NULL,
  `wind_speed` float DEFAULT NULL,
  `wind_gust` float DEFAULT NULL,
  `wind_deg` int DEFAULT NULL,
  `clouds` int DEFAULT NULL,
  `uvi` float DEFAULT NULL,
  `pop` float DEFAULT NULL,
  `rain` float DEFAULT NULL,
  `snow` float DEFAULT NULL,
  `weather_id` int DEFAULT NULL,
  `weather_main` varchar(128) DEFAULT NULL,
  `weather_description` varchar(128) DEFAULT NULL,
  `weather_icon` varchar(32) DEFAULT NULL,
  PRIMARY KEY (`district`,`dt`,`future_dt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
